package notification.core.recipient;import notification.core.recipient.Recipient;/** * Email-specific recipient. */public class EmailRecipient implements Recipient {    private final String email;    private final String language;    public EmailRecipient(            String email,            String language) {        this.email = email;        this.language = language;    }    public String getEmail() {        return email;    }    @Override    public String id() {        return email;    }    @Override    public String language() {        return language;    }}